#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


run_wizard() {

TOTAL_STAGES=12
PR=86

# Push keys live here: gitignored (*.local), mode 0600, and in the exact
# format `supabase secrets set --env-file` reads. Keep a copy with your backups.
cd "$(git rev-parse --show-toplevel)"
ENV_FILE="supabase/functions/.env.production.local"

# run CMD... shows the command, then runs it.
run() { printf '  %s$ %s%s\n' "$DIM" "$*" "$RESET"; "$@"; }
sb()  { npx --yes supabase "$@"; }

# check_outbox shows the newest push rows, for when a phone gets nothing.
check_outbox() {
  say "Newest rows in the push outbox:"
  sb db query --linked "select id, art, send_efter, sendt, fejl from public.push_udbakke order by id desc limit 10" || true
  note "sendt set: Apple/Google took it, so check the phone's notification settings."
  note "fejl = ingen_abonnement: that login has no device; tap 'Slå notifikationer til' again."
  note "fejl = 403: the VAPID keys don't match between Vercel and the function."
  note "Nothing set: the sender never ran; see 'If nothing arrives' in docs/ops/push-setup.md."
}

banner "Ship spec #74 with push notifications"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Check your setup"
say "This wizard deploys spec #74 to production and switches on push."
say "It runs each production command only after you say yes."
run git fetch -q origin spec/74-v1
if [[ "$(git rev-parse --abbrev-ref HEAD)" != "spec/74-v1" ]] ||
   [[ "$(git rev-parse HEAD)" != "$(git rev-parse origin/spec/74-v1)" ]]; then
  warn "Run this from a checkout of spec/74-v1 that matches origin/spec/74-v1."
  exit 1
fi
if ! docker info >/dev/null 2>&1; then
  warn "Docker isn't running. Start Docker Desktop (the backup needs it), then re-run."
  exit 1
fi
if [[ ! -f supabase/.temp/project-ref ]]; then
  say "This checkout isn't linked to a Supabase project yet."
  guess="$(git rev-parse --path-format=absolute --git-common-dir)/../supabase/.temp/project-ref"
  [[ -f "$guess" ]] && note "Your main checkout is linked to: $(cat "$guess")"
  ask LINK_REF "Production project ref:"
  run sb link --project-ref "$LINK_REF"
fi
PROJECT_REF="$(cat supabase/.temp/project-ref)"
FUNCTION_URL="https://${PROJECT_REF}.supabase.co/functions/v1/send-push"
say "Linked project: ${BOLD}${PROJECT_REF}${RESET}"
confirm "Is that your production project?" || { warn "Relink with: npx supabase link --project-ref <ref>"; exit 1; }

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Back up the database"
say "Supabase Free has no backups, so this dump is your only safety net."
note "Say no only if you took one in the last few minutes."
if confirm "Take a backup now?"; then
  B="backups/$(date +%Y-%m-%d_%H%M)"
  mkdir -p "$B"
  run sb db dump --linked --role-only -f "$B/roles.sql"
  run sb db dump --linked -f "$B/schema.sql"
  run sb db dump --linked --data-only --use-copy -f "$B/data.sql"
  ls -lh "$B"
  say "COPY blocks in data.sql: $(grep -c '^COPY' "$B/data.sql" || true) (should be well above 0)"
  grep -q "COPY public.medlem " "$B/data.sql" && say "Found the medlem table. ✓" || warn "No medlem table in the dump!"
  confirm "Does the backup look right?" || { warn "Stop here and check docs/ops/backup-and-rollback.md."; exit 1; }
  step "Copy $B somewhere off this laptop too, e.g. an encrypted cloud drive."
  pause "Press Enter when it's copied."
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Deploy the migrations"
say "First a dry run, which changes nothing:"
dry="$(sb db push --dry-run 2>&1 || true)"
printf '%s\n' "$dry" | sed 's/^/    /'
if grep -qi "up to date" <<<"$dry"; then
  say "Production already has every migration. ✓"
else
  say "You should see exactly these 11, from 20261101100000_kasserer.sql"
  say "to 20261102000000_spec74_review.sql. Nothing older."
  confirm "Is that what's listed?" || { warn "Stop: something unexpected would run."; exit 1; }
  confirm "Push them to production now?" || { warn "Nothing pushed. Re-run when ready."; exit 1; }
  run sb db push
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Check the scheduled jobs"
run sb db query --linked "select jobname, schedule, active from cron.job order by jobname"
say "You should see three active jobs:"
step "koer_automatik (0 * * * *): the hourly Gebyr automation"
step "push_sweep (30 seconds): sends waiting pushes"
step "cron_oprydning (17 3 * * *): clears old job logs"
confirm "Are all three there and active?" || {
  warn "pg_cron may be off. Turn it on in Dashboard → Database → Extensions,"
  warn "then ask Claude to schedule the jobs before you continue."
  open_url "https://supabase.com/dashboard/project/${PROJECT_REF}/database/extensions"
  exit 1
}

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Make the push keys"
if [[ -n "$(_existing VAPID_PRIVATE_KEY || true)" ]]; then
  VAPID_PUBLIC_KEY="$(_existing VAPID_PUBLIC_KEY)"
  say "Keys already exist in $ENV_FILE. Keeping them. ✓"
  note "A new pair would make every phone subscribe again."
else
  say "Making a VAPID key pair (the 'wax seal' for your pushes)."
  read -r gen_pub gen_priv < <(node -e '
    const c = require("crypto");
    const j = c.generateKeyPairSync("ec", { namedCurve: "prime256v1" }).privateKey.export({ format: "jwk" });
    const pub = Buffer.concat([Buffer.from([4]), Buffer.from(j.x, "base64url"), Buffer.from(j.y, "base64url")]);
    console.log(pub.toString("base64url") + " " + j.d);')
  write_env VAPID_PUBLIC_KEY "$gen_pub"
  write_env VAPID_PRIVATE_KEY "$gen_priv"
fi
if [[ -n "$(_existing PUSH_SEND_SECRET || true)" ]]; then
  PUSH_SEND_SECRET="$(_existing PUSH_SEND_SECRET)"
else
  write_env PUSH_SEND_SECRET "$(openssl rand -hex 32)"
fi
say "Apple and Google want a contact address in case your pushes misbehave."
ask VAPID_SUBJECT "Contact (mailto:you@example.com):"
[[ "$VAPID_SUBJECT" =~ ^(mailto:|https://) ]] || VAPID_SUBJECT="mailto:${VAPID_SUBJECT}"
write_env VAPID_SUBJECT "$VAPID_SUBJECT"
note "$ENV_FILE is gitignored. Keep a copy with your backups."

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Give the sender its keys"
say "Uploads VAPID_PUBLIC_KEY, VAPID_PRIVATE_KEY, VAPID_SUBJECT and PUSH_SEND_SECRET"
say "as Edge Function secrets. The values never show on screen."
confirm "Set the function secrets now?" || { warn "Skipped. Re-run to continue."; exit 1; }
run sb secrets set --project-ref "$PROJECT_REF" --env-file "$ENV_FILE"
sb secrets list --project-ref "$PROJECT_REF" | grep -E "VAPID_|PUSH_SEND_SECRET" || warn "Couldn't see the secrets listed."

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Deploy the sender"
confirm "Deploy the send-push Edge Function now?" || { warn "Skipped. Re-run to continue."; exit 1; }
run sb functions deploy send-push --project-ref "$PROJECT_REF" --no-verify-jwt
code="$(curl -s -o /dev/null -w '%{http_code}' -X POST "$FUNCTION_URL" || true)"
if [[ "$code" == "401" ]]; then
  say "The sender is live and rejects callers without the secret. ✓"
else
  warn "Expected 401 from $FUNCTION_URL but got $code. Check the function logs:"
  open_url "https://supabase.com/dashboard/project/${PROJECT_REF}/functions/send-push/logs"
  pause
fi

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Connect the database to the sender"
say "Stores the sender's address and password in Supabase Vault, so the"
say "database can ring the doorbell when a push is waiting."
confirm "Write the two Vault secrets now?" || { warn "Skipped. Re-run to continue."; exit 1; }
sql_file="$(umask 077 && mktemp)"
trap 'rm -f "$sql_file"' EXIT
cat > "$sql_file" <<SQL
do \$\$
declare v_id uuid;
begin
  select id into v_id from vault.secrets where name = 'push_send_url';
  if v_id is null then perform vault.create_secret('${FUNCTION_URL}', 'push_send_url');
  else perform vault.update_secret(v_id, '${FUNCTION_URL}'); end if;
  select id into v_id from vault.secrets where name = 'push_send_secret';
  if v_id is null then perform vault.create_secret('${PUSH_SEND_SECRET}', 'push_send_secret');
  else perform vault.update_secret(v_id, '${PUSH_SEND_SECRET}'); end if;
end \$\$;
SQL
run sb db query --linked -f "$sql_file"
rm -f "$sql_file"
run sb db query --linked "select name from vault.secrets where name like 'push_send_%' order by name"
reply="$(curl -s -X POST -H "Authorization: Bearer ${PUSH_SEND_SECRET}" "$FUNCTION_URL" || true)"
if [[ "$reply" == *'"sendt"'* ]]; then
  say "The sender accepts the secret: $reply ✓"
else
  warn "The sender answered: $reply. Check the function logs before you go on."
  open_url "https://supabase.com/dashboard/project/${PROJECT_REF}/functions/send-push/logs"
  pause
fi

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Give the app the public key"
printf '%s' "$VAPID_PUBLIC_KEY" | pbcopy 2>/dev/null && say "The public key is on your clipboard." \
  || say "Public key: $VAPID_PUBLIC_KEY"
open_url "https://vercel.com/dashboard"
step "Open the Boedekasse project → Settings → Environment Variables."
step "Add a variable. Key: VITE_VAPID_PUBLIC_KEY. Value: paste the public key."
step "Tick Production only, then Save."
note "It's the public half, so it's safe in the app. Vite reads it at build time."
pause "Press Enter when it's saved."

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Ship the app"
state="$(gh pr view "$PR" --json state --jq .state)"
if [[ "$state" == "MERGED" ]]; then
  say "PR #$PR is already merged. ✓"
else
  say "Merging PR #$PR puts spec/74-v1 on main, and Vercel builds main."
  note "The Anke reel (#84/#85) follows in a later PR."
  confirm "Mark PR #$PR ready and merge it into main now?" || { warn "Not merged. Re-run when ready."; exit 1; }
  run gh pr ready "$PR" || true
  run gh pr merge "$PR" --merge
fi
open_url "https://vercel.com/dashboard"
step "Open the Boedekasse project → Deployments. Wait for the new build to show Ready."
pause "Press Enter when it's Ready."
step "Open the app on your phone. Check Hjem, Giv bøde and Saldo still work."
confirm "Does the app work?" || {
  warn "Roll back the frontend: Vercel → Deployments → last good one → ⋯ → Promote to Production."
  warn "The database can stay. See docs/ops/backup-and-rollback.md, section 4A."
  exit 1
}

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Test on an iPhone"
say "You need two logins, so one can give the other a Bøde."
step "In Safari, open the app and tap Del → Føj til hjemmeskærm (iOS 16.4 or newer)."
step "Open it from the home screen and log in."
step "Profil → Notifikationer → 'Slå notifikationer til'. Allow notifications."
step "Lock the phone. From the other login, give this person two Bøder in one go."
step "Within about a minute, one push says '2 nye bøder i <Bødekasse>'."
step "Tap it. The app opens on your profile in that Bødekasse."
step "Turn 'Bøder til dig' off and give another Bøde. Nothing arrives."
step "Turn it back on. Give a Bøde and tap Fortryd at once. Nothing arrives."
confirm "Did all of that work on the iPhone?" || { check_outbox; pause "Press Enter to go on to Android."; }

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Test on Android"
step "In Chrome, open the app, then menu → Install app (or Add to Home screen)."
step "Open the installed app, log in, and repeat the iPhone steps 3 to 8."
if confirm "Did it all work on Android?"; then
  if confirm "Close #87 as done?"; then
    run gh issue close 87 --comment "Push is live in production. Checked on an installed iPhone and on Android: the push arrived, the tap opened the app, the toggle off stopped pushes, and Fortryd stopped the push."
  fi
else
  check_outbox
  warn "Leave #87 open and ask Claude, pasting the outbox rows above."
fi

finish
}

run_wizard "$@"; exit
